#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

/**
Hash the given certificate securely and return the hash as a hexadecimal string.
You can include openssh libraries.

@param cert The certificate to be hashed.

@return The securely hashed certificate as a hexadecimal string.
*/
char* hash_certificate(const char *cert) {
    if (cert == NULL) {
        return NULL; // Handle NULL input
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((const unsigned char *)cert, strlen(cert), hash);

    // Allocate memory for the hexadecimal string.
    // SHA256_DIGEST_LENGTH * 2 for each byte (0-255) represented by two hex chars.
    // +1 for the null terminator.
    char *hex_hash = (char *)malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    if (hex_hash == NULL) {
        return NULL; // Handle allocation failure
    }

    // Convert the binary hash to a hexadecimal string.
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hex_hash + (i * 2), "%02x", hash[i]);
    }
    hex_hash[SHA256_DIGEST_LENGTH * 2] = '\0'; // Null-terminate the string

    return hex_hash;
}
